-- PostgreSQL 18 plans a locking clause as a LockRows node above the query's
-- sort and below its Limit (grouping_planner); a subquery that locks keeps
-- its Subquery Scan, and a query without FROM has no rows to lock. Under
-- ANALYZE the node counts the rows it locked and returned.
CREATE TABLE t475 (a int, b int);
INSERT INTO t475 SELECT g % 10, g FROM generate_series(1, 100) g;
CREATE TABLE u475 (a int, c text);
INSERT INTO u475 SELECT g, 'x' || g FROM generate_series(1, 20) g;
ANALYZE t475;
ANALYZE u475;
EXPLAIN (COSTS OFF) SELECT * FROM t475 FOR UPDATE;
EXPLAIN (COSTS OFF) SELECT * FROM t475 WHERE a = 1 FOR SHARE;
EXPLAIN (COSTS OFF) SELECT * FROM t475 JOIN u475 ON t475.b = u475.a FOR UPDATE OF t475;
EXPLAIN (COSTS OFF) SELECT * FROM t475 ORDER BY b LIMIT 1 FOR UPDATE;
EXPLAIN (COSTS OFF) SELECT * FROM t475 ORDER BY b LIMIT 1 FOR NO KEY UPDATE SKIP LOCKED;
EXPLAIN (COSTS OFF) SELECT * FROM t475 ORDER BY b OFFSET 2 FOR KEY SHARE;
EXPLAIN (COSTS OFF) SELECT * FROM t475 FOR UPDATE OF t475 NOWAIT;
EXPLAIN (COSTS OFF) SELECT * FROM (SELECT * FROM t475 FOR UPDATE) s;
EXPLAIN (COSTS OFF) SELECT * FROM (SELECT * FROM t475 WHERE a = 2 FOR UPDATE) s WHERE b > 50;
EXPLAIN (COSTS OFF) SELECT 1 FOR UPDATE;
EXPLAIN (COSTS OFF) SELECT * FROM (VALUES (1), (2)) v FOR UPDATE;
EXPLAIN (COSTS OFF) SELECT * FROM t475 WHERE false FOR UPDATE;
EXPLAIN (COSTS OFF, FORMAT JSON) SELECT * FROM t475 WHERE a = 1 FOR UPDATE;
EXPLAIN (COSTS OFF, FORMAT YAML) SELECT * FROM t475 ORDER BY b LIMIT 2 FOR UPDATE;
CREATE FUNCTION analyzed475(query text) RETURNS SETOF text LANGUAGE plpgsql AS $$
DECLARE
  line text;
BEGIN
  FOR line IN EXECUTE 'EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) ' || query LOOP
    -- Memory figures are each server's own.
    RETURN NEXT regexp_replace(line, '(Memory|Memory Usage): \d+kB', '\1: NkB');
  END LOOP;
END
$$;
SELECT analyzed475('SELECT * FROM t475 WHERE a = 1 FOR UPDATE');
SELECT analyzed475('SELECT * FROM t475 WHERE a = 1 ORDER BY b OFFSET 3 LIMIT 4 FOR UPDATE');
SELECT analyzed475('SELECT * FROM t475 WHERE a < 3 ORDER BY b DESC FOR SHARE');
SELECT analyzed475('SELECT * FROM t475 WHERE false FOR UPDATE');
SELECT analyzed475('SELECT * FROM (SELECT * FROM t475 WHERE b > 95 FOR UPDATE) s');
SELECT * FROM t475 WHERE a = 1 FETCH FIRST 2 ROWS WITH TIES FOR UPDATE;
